{
  "expression": "div(gain, add(cost, multiply(0.1, overlap)))",
  "rationale": "Enhances the greedy baseline div(gain, cost) by penalizing candidates with high neighborhood overlap, favoring vertices whose closed neighborhoods more efficiently target unselected regions without redundant coverage."
}

{
  "expression": "div(gain, cost) + div(rarity, cost) - div(overlap, cost)",
  "rationale": "Extends the greedy reference by adding a rarity incentive (favoring vertices covering hard-to-cover elements) and subtracting an overlap penalty, both scaled inversely by vertex cost to preserve cost sensitivity."
}

{
  "expression": "div(gain, cost) + 0.35 * gain * rarity * (1.0 - overlap)",
  "rationale": "Enhances the greedy baseline by adding a bonus for covering rare, hard-to-cover vertices while preferring vertices with lower overlap (higher proportion of newly covered vertices in their neighborhood)."
}

{
  "expression": "div(gain, cost) + div(rarity, add(cost, overlap))",
